import unittest

from hourglass.rounding import label_spans, round_spans
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_spans([Span(543, 1027)], 15)
        self.assertEqual(result, [Span(540, 1020)])

    def test_halfway_rounds_up(self):
        result = round_spans([Span(15, 45)], 30)
        self.assertEqual(result, [Span(30, 60)])

    def test_exact_values_are_unchanged(self):
        result = round_spans([Span(60, 120)], 30)
        self.assertEqual(result, [Span(60, 120)])

    def test_end_can_reach_midnight(self):
        result = round_spans([Span(1000, 1438)], 30)
        self.assertEqual(result, [Span(990, 1440)])

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 30)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(0, 60)], step)


class LabelSpansTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:13")]
        self.assertEqual(
            label_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-12:00"), Span(780, 1020)]
        self.assertEqual(
            label_spans(spans, 60),
            ["08:00-12:00 (4h 0m)", "13:00-17:00 (4h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_spans([], 15), [])
